process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const GAV='';
const DEP=Buffer.from('','base64').toString();
async function jsonSafe(r){ const t=await r.text();
  const a=t.indexOf('['), o=t.indexOf('{');
  const i=(a>=0&&(a<o||o<0))?a:o; if(i<0) return null;
  try{ return JSON.parse(t.slice(i)); }catch(e){ return null; } }
async function putRaw(path,b64,msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'g3', content:b64}; if(sha) body.sha=sha;
  await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
}
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',
    headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name, code, scope:'global', active:true})});
  return await jsonSafe(r)||{};
}
async function off(id){ if(!id) return; await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',
  headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
const pause=ms=>new Promise(x=>setTimeout(x,ms));
async function main(){
  const out={VERSIJA:'G3'};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await jsonSafe(r);
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active&&/^TEMP/i.test(s.name||''))){ await off(t.id); }
  let s=await snip('TEMP g3 set', "update_option('ps_uxd_gav','"+GAV+"','no');");
  await pause(2000); await fetch(`${WP}/`,{headers:{Authorization:AUTH}}); await off(s.id);
  const sd=await snip('TEMP g3 deploy', DEP.replace(/^<\?php\s*/,''));
  await pause(2500);
  let resp=await fetch(`${WP}/?ps_g3_dep=1&k=dq7m3z`,{headers:{Authorization:AUTH}});
  out.deploy=await jsonSafe(resp);
  await fetch(`${WP}/?ps_g3_val=1&k=dq7m3z`,{headers:{Authorization:AUTH}});

  const {chromium}=await import('playwright');
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true, viewport:{width:1680,height:1050}});
  const page=await ctx.newPage();
  const jsErr=[]; page.on('pageerror',e=>jsErr.push(String(e).slice(0,200)));
  page.setDefaultTimeout(15000);
  try{ await page.goto(`${WP}/?ps_g3_log=1&k=dq7m3z`,{waitUntil:'networkidle',timeout:45000}); }catch(e){}
  await pause(3000);

  /* Ieskom neegzistuojancios prekes */
  await page.evaluate(()=>{ const i=document.getElementById('g-q');
    i.focus(); i.value='Testinis skanestas XYZ'; i.dispatchEvent(new Event('input',{bubbles:true})); });
  await pause(3500);
  out.rez=await page.evaluate(()=>{
    const r=document.getElementById('g-rez');
    return {tekstas:r.innerText.slice(0,160), yra_mygtukas:!!r.querySelector('.nauja')};
  });
  let png=await page.screenshot(); out.s1=await putRaw('screenshots/g3_nerasta.png', png.toString('base64'),'g3');

  /* Atveriam forma */
  await page.evaluate(()=>{ const b=document.querySelector('#g-rez .nauja'); if(b) b.click(); });
  await pause(1500);
  out.forma=await page.evaluate(()=>{
    const m=document.getElementById('gav-nauja');
    if(!m||m.hidden) return 'neatsidare';
    return {pav:(document.getElementById('n-pav')||{}).value,
      laukai:Array.prototype.map.call(m.querySelectorAll('input,select,textarea'),x=>x.id).filter(Boolean),
      kategoriju:(document.getElementById('n-kat')||{}).options.length,
      brendu:(document.getElementById('n-brendas')||{}).options.length,
      pilnumas:(document.getElementById('n-pilnumas')||{}).textContent};
  });
  png=await page.screenshot(); out.s2=await putRaw('screenshots/g3_forma.png', png.toString('base64'),'g3');

  /* Pildom ir kuriam */
  await page.evaluate(()=>{
    document.getElementById('n-pav').value='TESTAS Skanėstas šunims 100 g';
    document.getElementById('n-sku').value='GAVTEST001';
    document.getElementById('n-ean').value='4770000999123';
    document.getElementById('n-kaina').value='4,99';
    const k=document.getElementById('n-kat'); if(k.options.length>1) k.selectedIndex=1;
    k.dispatchEvent(new Event('change',{bubbles:true}));
    const a=document.getElementById('n-apras');
    a.value='Testinis skanėstas šunims, pagamintas iš džiovintos jautienos. Tinka kasdieniam skatinimui ir dresūrai, be dirbtinių priedų bei konservantų, lengvai virškinamas.';
    a.dispatchEvent(new Event('input',{bubbles:true}));
    document.getElementById('n-kaina').dispatchEvent(new Event('input',{bubbles:true}));
  });
  await pause(700);
  out.pilnumas_pries=await page.evaluate(()=>document.getElementById('n-pilnumas').textContent);
  await page.evaluate(()=>document.getElementById('n-kurti').click());
  await pause(4000);
  out.po_kurimo=await page.evaluate(()=>({
    modalas_uzdarytas:document.getElementById('gav-nauja').hidden,
    stat:(document.getElementById('n-stat')||{}).textContent,
    lentele:(document.querySelector('.psgav-t tbody')||{}).innerText.replace(/\n+/g,' | ').slice(0,200),
    pranesimas:(document.querySelector('.pr,.psgav-pr,#g-pr')||{}).textContent}));
  png=await page.screenshot(); out.s3=await putRaw('screenshots/g3_sukurta.png', png.toString('base64'),'g3');

  out.js_klaidos=jsErr.slice(0,6);
  await br.close(); await off(sd.id);
  r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const l2=await jsonSafe(r);
  out.liko_temp=(Array.isArray(l2)?l2:[]).filter(x=>x.active&&/^TEMP/i.test(x.name||'')).map(x=>x.name);
  await putRaw('analize/g3.json', Buffer.from(JSON.stringify(out,null,2)).toString('base64'),'g3');
}
main().catch(e=>{});
